def _usage_overall(raw):
    """
    Parse usage/overall.
    """
    usage = {}
    for line in raw:
        if line.startswith("usage"):
            usage["usage"] = line.split()[1]
        if line.startswith("overall"):
            usage["overall"] = line.split()[1]
        if line.startswith("cpu"):
            usage["cpu"] = line.split()[1]
        if line.startswith("mem"):
            usage["mem"] = line.split()[1]
        if line.startswith("swap"):
            usage["swap"] = line.split()[1]
        if line.startswith("net"):
            usage["net"] = line.split()[1]
        if line.startswith("io"):
            usage["io"] = line.split()[1]
        if line.startswith("system"):
            usage["system"] = line.split()[1]
        if line.startswith("uptime"):
            usage["uptime"] = line.split()[1]
        if line.startswith("load"):
            usage["load"] = line.split()[1]
    return usage

